import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/outlierr/2022_crime.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

df_crime = pd.read_csv(DATASET_PATH)
df_adj = pd.read_csv(ADJACENCY_PATH)

borough_neighbors = df_adj.groupby('borough')['neighbor'].apply(list).to_dict()

def compute_neighbor_avg(borough, remaining_boroughs):
    neighbors = borough_neighbors.get(borough, [])
    valid_neighbors = [n for n in neighbors if n in remaining_boroughs['borough'].values]
    if not valid_neighbors:
        return np.nan
    neighbor_crimes = remaining_boroughs[remaining_boroughs['borough'].isin(valid_neighbors)]['Crime_value']
    return neighbor_crimes.mean()

remaining_boroughs = df_crime.copy()
outliers = []

while True:
    remaining_boroughs['neighbor_avg'] = remaining_boroughs['borough'].apply(
        lambda b: compute_neighbor_avg(b, remaining_boroughs)
    )
    remaining_boroughs = remaining_boroughs.dropna()
    if remaining_boroughs.empty:
        break
    remaining_boroughs['deviation'] = remaining_boroughs['Crime_value'] - remaining_boroughs['neighbor_avg']
    max_dev = remaining_boroughs['deviation'].abs().max()
    if max_dev == 0:
        break
    threshold = 2 * remaining_boroughs['deviation'].std()
    extreme_borough = remaining_boroughs.loc[remaining_boroughs['deviation'].abs().idxmax()]
    if abs(extreme_borough['deviation']) > threshold:
        outliers.append(extreme_borough)
        remaining_boroughs = remaining_boroughs[remaining_boroughs['borough'] != extreme_borough['borough']]
    else:
        break

westminster_outlier = None
for o in outliers:
    if o['borough'] == 'Westminster':
        westminster_outlier = o
        break

if westminster_outlier is not None:
    deviation = westminster_outlier['deviation']
    if deviation > 0:
        print(f"FINAL ANSWER: OUTLIER - HIGH (deviation = {deviation})")
    else:
        print(f"FINAL ANSWER: OUTLIER - LOW (deviation = {deviation})")
else:
    west_row = df_crime[df_crime['borough'] == 'Westminster'].iloc[0]
    neighbors = borough_neighbors.get(west_row['borough'], [])
    valid_neighbors = [n for n in neighbors if n in remaining_boroughs['borough'].values]
    if not valid_neighbors:
        west_neighbor_avg = np.nan
    else:
        west_neighbor_crimes = remaining_boroughs[remaining_boroughs['borough'].isin(valid_neighbors)]['Crime_value']
        west_neighbor_avg = west_neighbor_crimes.mean()
    west_deviation = west_row['Crime_value'] - west_neighbor_avg

    final_dev_mean = remaining_boroughs['deviation'].mean()
    final_dev_std = remaining_boroughs['deviation'].std()
    if np.isnan(final_dev_std):
        final_dev_std = 1.0
    z_score = (west_deviation - final_dev_mean) / final_dev_std

    if abs(z_score) > 2:
        if west_deviation > 0:
            print(f"FINAL ANSWER: OUTLIER - HIGH (z = {z_score})")
        else:
            print(f"FINAL ANSWER: OUTLIER - LOW (z = {z_score})")
    else:
        print(f"FINAL ANSWER: NOT AN OUTLIER (z = {z_score})")
